const context = $json;
const allowedTargets = new Set(String(context.allowed_targets_csv || '').split(',').map((value) => value.trim()).filter(Boolean));
if (!allowedTargets.has(context.target)) {
  return [{ json: { ...context, blocked_reason: 'target_not_allowlisted', delivery_status: 'cancelled' } }];
}
return [{ json: { ...context, target_allowed: true, delivery_status: context.dry_run ? 'cancelled' : 'confirmed' } }];

const item = $json;
const whatsappGroupUrl = String(item.whatsapp_group_url || '').trim();
if (!/^https:\/\/(chat\.whatsapp\.com|whatsapp\.com\/channel|wa\.me)\//i.test(whatsappGroupUrl)) {
  throw new Error('whatsapp_group_url obrigatorio para copy Instagram');
}
const formatMoney = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const numberValue = Number(value);
  if (Number.isFinite(numberValue)) return `R$ ${numberValue.toFixed(2).replace('.', ',')}`;
  return String(value).trim();
};
const formatRating = (value) => {
  const rating = Number(value);
  if (Number.isFinite(rating)) return rating.toFixed(1).replace('.', ',');
  return String(value || '').trim();
};
const hashtag = String(item.primary_subniche || 'ofertas')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '') || 'ofertas';
const metrics = [
  formatMoney(item.price) ? `💸 ${formatMoney(item.price)}` : null,
  formatRating(item.rating) ? `⭐ ${formatRating(item.rating)}/5 na Shopee` : null,
].filter(Boolean).join('\n');
const captionBase = [
  [`🔥 ${item.product_name}`, `Copie o link da oferta: ${String(item.offer_link || '').trim()}`].filter(Boolean).join('\n'),
  metrics,
  `💬 Quer receber mais ofertas assim?\nEntre no grupo do WhatsApp: ${whatsappGroupUrl}`,
  '⚠️ Preco e disponibilidade podem mudar.',
  `#ad #shopee #${hashtag} #achadinhos`,
].filter(Boolean).join('\n\n');
return [{ json: { ...item, whatsapp_group_url: whatsappGroupUrl, caption_base: captionBase } }];

const item = $json;
const urls = item.instagram_format === 'reels' ? [item.video_url] : (item.image_urls || []).slice(0, 10);
const media_validation = urls.filter(Boolean).map((url) => ({ url, expected: String(url).includes('.mp4') ? 'video/' : 'image/', status: 'pending_http_range_validation' }));
return [{ json: { ...item, media_validation, media_revalidation_required: true } }];

const original = $json;
const imageUrls = Array.isArray(original.image_urls) ? original.image_urls.filter(Boolean).slice(0, 10) : [];
if (imageUrls.length < 2) {
  throw new Error('carousel requires between 2 and 10 image urls');
}
return imageUrls.map((imageUrl, index) => ({ json: { ...original, carousel_image_url: imageUrl, carousel_item_index: index + 1, carousel_item_total: imageUrls.length } }));

const original = $('Montar Copy Instagram').first().json;
const childResponses = $input.all();
const childIds = childResponses.map((item) => String(item.json.id || item.json.creation_id || '').trim()).filter(Boolean);
if (childIds.length < 2 || childIds.length > 10) {
  throw new Error('carousel requires between 2 and 10 child containers');
}
return [{ json: { ...original, instagram_business_account_id: original.instagram_business_account_id, caption_base: original.caption_base, carousel_child_ids: childIds.join(','), carousel_child_creation_ids: childIds } }];

const item = $json;
const creationId = String(item.creation_id || item.id || '').trim();
if (!creationId) {
  throw new Error('instagram container creation id ausente');
}
return [{ json: { ...item, creation_id: creationId } }];

const statusResponse = $json;
const normalized = $('Normalizar Container Criado').first().json;
let original = null;
try {
  original = $('Montar Payload Pai Carrossel').first().json;
} catch (error) {
  original = null;
}
if (!original || !String(original.instagram_business_account_id || '').trim()) {
  original = $('Montar Copy Instagram').first().json;
}
return [{ json: { ...original, creation_id: String(normalized.creation_id || '').trim(), container_status: String(statusResponse.status_code || '').trim(), instagram_graph_container_id: String(statusResponse.id || '').trim() } }];
